import{z as p,x as E,o as r,c as A,q as n,j as l,D as s,d as e,s as o,S as d,b as t}from"./chunks/framework.C8m1ZpeB.js";const T=JSON.parse('{"title":"磁盘调度","description":"","frontmatter":{"title":"磁盘调度","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/disk-sched.md","filePath":"cs/disk-sched.md","lastUpdated":1791413859000}'),m={name:"cs/disk-sched.md"};function c(S,a,h,B,C,u){const i=E("Mermaid");return r(),A("div",null,[a[2]||(a[2]=n('<h1 id="磁盘调度" tabindex="-1">磁盘调度 <a class="header-anchor" href="#磁盘调度" aria-label="Permalink to &quot;磁盘调度&quot;">​</a></h1><div class="epigraph"><p>旋转磁盘上，请求顺序决定寻道时间；电梯算法让磁头单向扫过，避免饥饿与来回抖动。</p><footer>—— 据 Silberschatz et al., Operating System Concepts；Teorey and Pinkerton, A comparative analysis of disk scheduling policies, 1972 整理</footer></div><p><a href="/cs/setuid-sticky">上一课</a>产生一串读盘与回写请求。若按到达序（FCFS）送给磁头，短寻道与长寻道混排，平均等待差。缺口是<strong>磁盘调度</strong>：在可旋转介质上对块请求排序。本课以寻道为主，闪存只作边界对照。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>机械盘的时间在寻道与旋转，不在总线。<a href="/cs/scheduling-metrics">调度指标</a>换成：平均寻道、公平（内磁道不要饿死）。SSTF 总选最近请求，易饿外圈。SCAN/LOOK（电梯）扫到头再反向；C-SCAN 只单向服务，回来不服务，公平些。缺口不是 inode，而是请求队列上的排序。</p><p>本课不把 NCQ 与盘片内部重排的固件当主干实现。</p><p><span class="marginnote">闪存没有寻道，调度目标变成擦除块、磨损与并行通道。教学仍用机械电梯讲「请求顺序是资源」。SSD 上盲目 SCAN 无意义。</span></p><p><span class="marginnote">数字实例：磁头在 53 柱面，队列是 98、183、37、122、14、124、65、67。FCFS 照到达序走，总寻道 \\(|53-98|+|98-183|+\\cdots=640\\) 个柱面；LOOK 先扫完上行再折返，只走 \\((183-53)+(183-14)=299\\)——同一批请求，排序把移动量砍了一半多。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>维护按柱面排序的待服务队列。LOOK：向当前方向走到最远请求再折返。内核把缓冲回写与用户读混在同一队列时，要避免写风暴挡住读——这是策略，不是新硬件。设备完成仍走<a href="/cs/interrupt-bottom-half">中断下半部</a>，完成的请求从队列消失。</p>',10)),(r(),l(d,null,{default:s(()=>[o(i,{id:"mermaid-28",class:"mermaid",graph:"flowchart%20TD%0A%20%20Q%5B%22%E8%84%8F%E9%A1%B5%E4%B8%8E%E8%AF%BB%E8%AF%B7%E6%B1%82%22%5D%20--%3E%20SORT%5B%22%E6%8C%89%E6%9F%B1%E9%9D%A2%E6%8E%92%E5%BA%8F%22%5D%0A%20%20SORT%20--%3E%20SCAN%5B%22SCAN%2FLOOK%20%E6%9C%8D%E5%8A%A1%22%5D%0A%20%20SCAN%20--%3E%20IRQ%5B%22%E5%AE%8C%E6%88%90%E4%B8%AD%E6%96%AD%22%5D%0A"})]),fallback:s(()=>[...a[0]||(a[0]=[e(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=t("h2",{id:"机制",tabindex:"-1"},[e("机制 "),t("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=t("p",null,[e("磁盘调度是 I/O 版的电梯：与 CPU 的 CFS 不同，这里优化的是机械移动，不是虚拟时间。但它同样能制造饥饿，所以 SSTF 不是默认正确答案。与页置换一起：回写时机由脏页策略决定，"),t("strong",null,"顺序"),e("由本课决定。错误地把随机脏页立刻刷盘，会把电梯打成随机寻道。")],-1)),a[5]||(a[5]=t("p",null,"块号与柱面的映射由驱动与盘片几何（或 LBA 后的近似）给出；教学用一维柱面足够。",-1)),(r(),l(d,null,{default:s(()=>[o(i,{id:"mermaid-38",class:"mermaid",graph:"flowchart%20LR%0A%20%20H0%5B%22%E7%A3%81%E5%A4%B4%E5%9C%A8%2053%22%5D%20--%3E%20H1%5B%2265%22%5D%20--%3E%20H2%5B%2267%22%5D%20--%3E%20H3%5B%2298%22%5D%20--%3E%20H4%5B%22122%22%5D%20--%3E%20H5%5B%22124%22%5D%20--%3E%20H6%5B%22183%EF%BC%9A%E4%B8%8A%E8%A1%8C%E6%9C%80%E8%BF%9C%E8%AF%B7%E6%B1%82%22%5D%20--%3E%20H7%5B%22%E6%8A%98%E8%BF%94%2037%22%5D%20--%3E%20H8%5B%2214%EF%BC%9A%E6%94%B6%E5%B7%A5%22%5D%0A"})]),fallback:s(()=>[...a[1]||(a[1]=[e(" Loading... ",-1)])]),_:1})),a[6]||(a[6]=n('<p>这张图回答「LOOK 具体怎么走」：只走到「该方向上最远的请求」（183）就折返，不像 SCAN 一直蹭到盘物理末端（199）才回头——省掉 183 到 199 再折回来的空跑。这就是 LOOK 与 SCAN 的唯一差别：LOOK「看到没请求就回头」，SCAN「非到头不可」。</p><p><span class="marginnote">直觉类比：电梯不会为每个楼层按钮单独跑一趟——它先把上行沿途的按钮都按了，到最高一层有人等再折返下行。SSTF 的毛病相当于电梯哪层按钮离得近先停哪，结果顶层那位可以等一下午：最近优先 ≠ 公平。</span></p><p><span class="marginnote">为什么这课值得记：机械盘上随机寻道约几毫秒一次，顺序读写能快上百倍。错误地让每个脏页一变就立刻刷盘（write-through 式回写），等于把电梯算法亲手拆成随机寻道——回写时机交给脏页策略、顺序交给调度器，两件事分开管才保得住吞吐。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入 RAID 条带的全部调度，不把网络盘的 RTT 当寻道。也不声称 Linux CFQ/BFQ/mq-deadline 与 SCAN 同构；现代多队列是另一实现。闪存与持久内存把「电梯」从主干里降为历史对照。</p><p>旋转延迟与传输时间在教学模型里常并入「服务时间」；电梯主要打寻道这一项。</p><p>闪存翻译层自己会重排，主机调度器看到的 LBA 顺序不等于芯片顺序。</p><p>后课默认：块请求可以排序后发给设备。多核与 NVMe 上，单队列电梯被一把提交锁封顶，下一课多队列块层。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>机械盘上顺序就是性能；LOOK/C-SCAN 权衡平均与饥饿。</li><li>闪存目标不同，不要把 SCAN 当普适。</li><li>单队列电梯的锁瓶颈是下一课 blk-mq 的缺口。</li><li>出处：Teorey and Pinkerton, 1972；Silberschatz et al., <em>OSC</em>；Tanenbaum <em>MOS</em>。</li></ul>',10))])}const D=p(m,[["render",c]]);export{T as __pageData,D as default};
